### Catching and inspecting Joi errors

Source: https://github.com/hapijs/joi/blob/master/_autodocs/api-reference/errors.md

Demonstrates how to check if a validation error is a Joi error and access its details, such as the path, type, and message.

```js
const Joi = require('joi');

const schema = Joi.object({
    role: Joi.string().valid('admin', 'user').required()
});

const { error } = schema.validate({});
if (error) {
    if (Joi.isError(error)) {
        console.error(error.details.map((d) => d.path.join('.')).join(', '));   // 'role'
        console.error(error.details[0].type);                                    // 'any.required'
        console.error(error.details[0].message);                                 // '"role" is required'
    }
    else {
        console.error('Not a joi error:', error);
    }
}
```

